import React, { useState, createContext } from "react";
import { Cog6ToothIcon, HomeIcon, FlagIcon, ChartBarIcon } from "@heroicons/react/24/outline";

export const SectionContext = createContext();

const Sidebar = ({ activeSection, setActiveSection }) => (
  <aside className="w-20 bg-white h-full flex flex-col items-center py-6 shadow-md">
    <div className="mb-8 flex flex-col gap-6">
      <button
        className={`h-10 w-10 flex items-center justify-center rounded-lg ${activeSection === 'home' ? 'bg-primary/10 border-primary border' : ''}`}
        onClick={() => setActiveSection('home')}
        title="Home"
      >
        <HomeIcon className={`h-7 w-7 ${activeSection === 'home' ? 'text-primary' : 'text-gray-400'}`} />
      </button>
      <button
        className={`h-10 w-10 flex items-center justify-center rounded-lg ${activeSection === 'goals' ? 'bg-primary/10 border-primary border' : ''}`}
        onClick={() => setActiveSection('goals')}
        title="Goals"
      >
        <FlagIcon className={`h-7 w-7 ${activeSection === 'goals' ? 'text-primary' : 'text-gray-400'}`} />
      </button>
      <button
        className={`h-10 w-10 flex items-center justify-center rounded-lg ${activeSection === 'overview' ? 'bg-primary/10 border-primary border' : ''}`}
        onClick={() => setActiveSection('overview')}
        title="Full Overview"
      >
        <ChartBarIcon className={`h-7 w-7 ${activeSection === 'overview' ? 'text-primary' : 'text-gray-400'}`} />
      </button>
    </div>
  </aside>
);

const Topbar = () => (
  <header className="flex items-center justify-between px-8 py-4 bg-white shadow-sm">
    <h1 className="text-2xl font-bold tracking-tight text-primary">Proxima</h1>
    <Cog6ToothIcon className="h-7 w-7 text-gray-400 cursor-pointer" />
  </header>
);

const Layout = ({ children }) => {
  const [activeSection, setActiveSection] = useState('home');

  return (
    <SectionContext.Provider value={{ activeSection, setActiveSection }}>
      <div className="flex h-screen bg-gradient-to-br from-blue-50 via-white to-emerald-50">
        <Sidebar activeSection={activeSection} setActiveSection={setActiveSection} />
        <div className="flex-1 flex flex-col">
          <Topbar />
          <main className="flex-1 p-8 overflow-y-auto">{children}</main>
        </div>
      </div>
    </SectionContext.Provider>
  );
};

export default Layout;
